    counts = {}
    for row in grid:
        for value in row:
            counts[value] = counts.get(value, 0) + 1
    bg = max(counts, key=counts.get)
    out = [row[:] for row in grid]

    def runs(edge):
        result = []
        i = 0
        while i < len(edge):
            if edge[i] == bg:
                i += 1
                continue
            color = edge[i]
            j = i + 1
            while j < len(edge) and edge[j] == color:
                j += 1
            result.append((color, i, j))
            i = j
        return result

    candidates = []
    # Opposite horizontal edges
    for color, a, b in runs(grid[0]):
        for color2, c, d in runs(grid[-1]):
            if color == color2 and b - a == d - c:
                candidates.append(("tb", color, a, b, c, d))
    # Opposite vertical edges
    left = [grid[r][0] for r in range(h)]
    right = [grid[r][-1] for r in range(h)]
    for color, a, b in runs(left):
        for color2, c, d in runs(right):
            if color == color2 and b - a == d - c:
                candidates.append(("lr", color, a, b, c, d))

    if not candidates:
        return out

    orientation, bar_color, a, b, c, d = candidates[0]
    bar_cells = set()
    if orientation == "tb":
        for col in range(a, b):
            bar_cells.add((0, col))
        for col in range(c, d):
            bar_cells.add((h - 1, col))
    else:
        for row in range(a, b):
            bar_cells.add((row, 0))
        for row in range(c, d):
            bar_cells.add((row, w - 1))

    markers = []
    particles = [
        (r, col, grid[r][col])
        for r in range(h) for col in range(w)
        if grid[r][col] != bg and grid[r][col] != bar_color
    ]

    for r, col, color in particles:
